            'u_colors', 'u_colorsCount',
            'u_softness', 'u_noise', 'u_twist', 'u_distortion', 'u_swirl', 'u_grainMixer', 'u_grainOverlay', 'u_grainSize',
            'u_bandCount', 'u_center', 'u_proportion', 'u_noiseFrequency',
