            'u_color1', 'u_color2', 'u_color3', 'u_color4', 'u_color5', 'u_color6',
            'u_speed', 'u_radius', 'u_colorC', 'u_colorM', 'u_colorY', 'u_colorK', 'u_minDot', 'u_gridNoise',
            'u_floodC', 'u_floodM', 'u_floodY', 'u_floodK', 'u_gainC', 'u_gainM', 'u_gainY', 'u_gainK',
