            if (u.u_fit) gl.uniform1f(u.u_fit, state.fit);
            if (u.u_rotation) gl.uniform1f(u.u_rotation, state.rotation);
            if (u.u_scale) gl.uniform1f(u.u_scale, Math.max(isImageFilter ? 0.05 : 0.01, state.scale));
